#!/usr/bin/env python3
import csv, html, json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
rows = list(csv.DictReader((root/'output/rewrite-master-enriched.csv').open(newline='', encoding='utf-8')))
snap = {x['source_key']: x for x in json.load((root/'output/cvr-source-snapshot.json').open(encoding='utf-8'))}
def esc(x): return html.escape(str(x or ''), quote=True)
def kind(r): return {'Apartment':'apartments','Villa':'villas','Houses':'houses'}.get(r['property_type'],'other')
def area(r): return r.get('property_area') or r.get('property_city') or 'Da Nang'
cards=[]
for r in rows:
    urls=snap.get(r['source_key'],{}).get('image') or []
    local=[]
    for j,u in enumerate(urls,1):
        matches=list((root/r['image_dir']).glob(f'{j:02d}.*'))
        if matches: local.append('../'+str(matches[0].relative_to(root)))
    images='|'.join(local); first=local[0] if local else ''
    cards.append(f'''<article class="card" data-kind="{kind(r)}" data-area="{esc(area(r))}" data-building="{esc(r.get('building_name') or 'Standalone')}"><div class="cover"><div class="cover-open" data-images="{esc(images)}">{('<button class="slide-prev" type="button">‹</button><img src="'+esc(first)+'" alt="'+esc(r['rewritten_title'])+'"><button class="slide-next" type="button">›</button>') if first else '<span class="no-image">No local image</span>'}</div></div><div class="body"><div class="meta">{esc(r['source_key'])} · HTTP {esc(r['source_http_status'])}</div><h2>{esc(r['rewritten_title'])}</h2><p class="facts">{esc(r['public_price'])} {esc(r['price_currency'])}/month · {esc(r['bedrooms'])} bd · {esc(r['size'])} sqm</p><p class="address">Da Nang · {esc(area(r))}</p><p class="seller">{esc(r.get('building_name') or 'Standalone listing')} · {esc(r['property_type'])}</p><a class="source" href="{esc(r['source_url_internal'])}" target="_blank" rel="noreferrer">Open source ↗</a><div class="evidence"><strong>Features:</strong> {esc(r.get('property_features') or 'None captured')}<br><strong>Images:</strong> {len(local)} · <strong>Building ID:</strong> {esc(r.get('building_id') or '—')}</div><div class="gallery">{''.join('<button class="thumb" type="button" data-src="'+esc(x)+'"><img loading="lazy" src="'+esc(x)+'" alt=""></button>' for x in local)}</div></div></article>''')
areas=sorted({area(r) for r in rows}); buildings=sorted({r.get('building_name') for r in rows if r.get('building_name')})
chips=''.join(f'<label class="filter-chip"><input type="checkbox" data-filter="area" value="{esc(x)}"><span>{esc(x)}</span></label>' for x in areas)
bchips=''.join(f'<label class="filter-chip"><input type="checkbox" data-filter="building" value="{esc(x)}"><span>{esc(x)}</span></label>' for x in buildings)
doc='''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>House Rental Da Nang · CVR review</title><style>@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;700;800&display=swap');:root{{--ink:#17343a;--muted:#536264;--card:#fff;--accent:#9a7b4f;--line:#d6dfdc;--paper:#f7f6f1}}*{{box-sizing:border-box}}body{{margin:0;background:linear-gradient(135deg,#dce7e5 0,#f7f6f1 55%,#eee5d6 100%);color:var(--ink);font-family:Manrope,sans-serif}}header,main{{max-width:1500px;margin:auto;padding-left:24px;padding-right:24px}}header{{padding-top:48px;padding-bottom:28px;display:flex;justify-content:space-between;gap:24px;align-items:end}}h1{{font-size:clamp(2rem,5vw,4.8rem);letter-spacing:-.08em;line-height:.92;margin:0;max-width:800px}}header p{{max-width:420px;color:var(--muted);font-size:.85rem;line-height:1.6;margin:0}}.meta,.facts{{font:500 .7rem 'DM Mono',monospace;text-transform:uppercase;letter-spacing:.05em;color:var(--muted)}}.filters{{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:0 auto 18px;padding:0 24px;max-width:1500px}}.filter-chip input{{position:absolute;opacity:0}}.filter-chip span{{display:block;padding:9px 13px;border:1px solid #cbd6ce;border-radius:999px;background:#fff;color:#42514a;cursor:pointer}}.filter-chip input:checked+span{{background:var(--ink);color:#fff}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:20px;padding-bottom:70px}}.card{{background:var(--card);border:1px solid var(--line);box-shadow:7px 7px 0 #cdd8cf;overflow:hidden}}.cover{{aspect-ratio:4/3;background:#d8ded9;overflow:hidden}}.cover-open{{position:relative;width:100%;height:100%;display:flex;align-items:center;justify-content:center}}.cover-open img{{width:100%;height:100%;object-fit:cover}}.slide-prev,.slide-next{{position:absolute;top:50%;transform:translateY(-50%);z-index:1;width:34px;height:34px;border:0;border-radius:50%;background:#0e252acc;color:#fff;font-size:1.6rem;cursor:pointer}}.slide-prev{{left:10px}}.slide-next{{right:10px}}.no-image{{font:500 .75rem 'DM Mono',monospace;text-transform:uppercase;color:var(--muted)}}.body{{padding:17px 18px 20px}}h2{{font-size:1.15rem;line-height:1.17;letter-spacing:-.04em;margin:10px 0}}.facts{{color:var(--accent);margin:0 0 12px}}.address{{font-size:.86rem;margin:8px 0;color:#303d37}}.seller{{font-size:.78rem;color:var(--muted);margin:8px 0 15px}}.source{{font-size:.78rem;font-weight:800;color:var(--ink);text-decoration:none;border-bottom:2px solid var(--accent);padding-bottom:2px}}.evidence{{margin-top:15px;padding-top:12px;border-top:1px solid var(--line);font-size:.78rem;line-height:1.7;color:var(--muted)}}.gallery{{display:flex;gap:5px;overflow:auto;margin-top:17px}.thumb{{padding:0;border:0;background:none;cursor:pointer}.gallery img{{width:58px;height:45px;object-fit:cover;display:block;border:1px solid var(--line)}}.is-hidden{{display:none}}@media(max-width:650px){{header{{display:block;padding-top:32px}}header p{{margin-top:18px}}.grid{{grid-template-columns:1fr}}}}</style></head><body><header><div><div class="meta">House Rental Da Nang / CVR / internal review</div><h1>Chọn từng căn trước khi import.</h1></div><p>49 listing Da Nang. Mở source, xem ảnh local và đối chiếu building, khu vực, features, giá trước khi đồng bộ.</p></header><div class="filters"><b>Loại</b><label class="filter-chip"><input type="checkbox" data-filter="kind" value="" checked><span>Tất cả</span></label><label class="filter-chip"><input type="checkbox" data-filter="kind" value="apartments"><span>Căn hộ</span></label><label class="filter-chip"><input type="checkbox" data-filter="kind" value="villas"><span>Villa</span></label><label class="filter-chip"><input type="checkbox" data-filter="kind" value="houses"><span>Nhà</span></label></div><div class="filters"><b>Khu vực</b>{chips}</div><div class="filters"><b>Building</b>{bchips}</div><main><div class="grid">{''.join(cards)}</div></main><script>document.querySelectorAll('.cover-open').forEach(b=>{{let a=b.dataset.images?b.dataset.images.split('|').filter(Boolean):[],i=0,img=b.querySelector('img');b.querySelector('.slide-prev')?.addEventListener('click',e=>{{e.stopPropagation();i=(i+a.length-1)%a.length;img.src=a[i]}});b.querySelector('.slide-next')?.addEventListener('click',e=>{{e.stopPropagation();i=(i+1)%a.length;img.src=a[i]}})}});document.querySelectorAll('.thumb').forEach(t=>t.addEventListener('click',()=>t.closest('.card').querySelector('img').src=t.dataset.src));const fs=[...document.querySelectorAll('.filters input')];function apply(){{let get=k=>fs.filter(x=>x.checked&&x.dataset.filter===k&&x.value).map(x=>x.value),a=get('area'),b=get('building'),k=get('kind');document.querySelectorAll('.card').forEach(c=>c.classList.toggle('is-hidden',(a.length&&!a.includes(c.dataset.area))||(b.length&&!b.includes(c.dataset.building))||(k.length&&!k.includes(c.dataset.kind))))}}fs.forEach(x=>x.addEventListener('change',()=>{{if(!x.value)fs.filter(y=>y.dataset.filter===x.dataset.filter&&y.value).forEach(y=>y.checked=false);apply()}}));</script></body></html>'''
(root/'output/cvr-apartments-dashboard.html').write_text(doc.replace('{{','{').replace('}}','}').replace('{chips}',chips).replace('{bchips}',bchips).replace("{''.join(cards)}",''.join(cards)),encoding='utf-8')
print('Wrote card dashboard',len(rows),'listings')
